 var hash=hasher.HashPassword(u,password);await Db.Exec(c,tx,"UPDATE dbo.AppUsers SET Email=@e,EmailNormalized=@en,PasswordHash=@h,MustChangePassword=1,SecurityStamp=NEWID(),Disabled=0,FailedAttempts=0,LockedUntil=NULL WHERE WorkspaceId=@w AND MemberId=@m AND IsOwner=0; IF @@ROWCOUNT=0 INSERT dbo.AppUsers(Id,WorkspaceId,Email,EmailNormalized,PasswordHash,MemberId,IsOwner,Disabled,MustChangePassword,FailedAttempts) VALUES(NEWID(),@w,@e,@en,@h,@m,0,0,1,0)",("@h",hash),("@w",u.Workspace),("@m",memberId),("@e",email),("@en",email.ToUpperInvariant()));await tx.CommitAsync();return Results.Json(new{ok=true});}).RequireAuthorization();
